import React from "react";
import {AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig} from "remotion";

export const C = {bg: "#0b0e13", panel: "#141922", line: "#2a3240", text: "#f1f4f8", dim: "#9aa6b8", accent: "#5eead4"};
export const FONT = "Segoe UI, system-ui, sans-serif";
export const MONO = "Consolas, 'Courier New', monospace";

export const useIn = (delay: number, damping = 200) => {
  const f = useCurrentFrame();
  const {fps} = useVideoConfig();
  return spring({frame: f - delay, fps, config: {damping}});
};

export const Reveal: React.FC<{delay: number; y?: number; style?: React.CSSProperties; children: React.ReactNode}> = ({delay, y = 40, style, children}) => {
  const e = useIn(delay);
  return <div style={{opacity: e, transform: `translateY(${interpolate(e, [0, 1], [y, 0])}px)`, ...style}}>{children}</div>;
};

export const Stage: React.FC<{children: React.ReactNode}> = ({children}) => {
  const f = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const out = interpolate(f, [durationInFrames - 14, durationInFrames], [1, 0], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  return <AbsoluteFill style={{background: C.bg, color: C.text, fontFamily: FONT, opacity: out}}>{children}</AbsoluteFill>;
};

