  const e = useIn(delay);
  const f = useCurrentFrame();
  const open = lock ? interpolate(f, [unlockAt, unlockAt + 10], [0, 1], clamp) : 0;
  const lit = lock && open > 0.5;
  return (
    <div style={{height: 120, borderRadius: 22, background: C.panel, border: `3px solid ${lit ? C.accent : C.line}`, boxShadow: lit ? `0 0 40px ${C.accent}44` : "none", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 40px", opacity: e, transform: `translateX(${interpolate(e, [0, 1], [-60, 0])}px)`}}>
