import React from "react";
import {interpolate, useCurrentFrame} from "remotion";
import {C, MONO, Reveal, Stage, useIn} from "./lib/kit";

const clamp = {extrapolateLeft: "clamp", extrapolateRight: "clamp"} as const;
const CMDS = [".\\setup.ps1", "python scripts/bootstrap_third_party.py", "python -m jarvis health", "python scripts/dev_start.py"];
const START = (i: number) => 28 + i * 52;
const SPEED = 1.6;

const Line: React.FC<{i: number}> = ({i}) => {
  const f = useCurrentFrame();
  const cmd = CMDS[i];
  const n = Math.max(0, Math.min(cmd.length, Math.floor((f - START(i)) * SPEED)));
  const doneAt = START(i) + cmd.length / SPEED + 4;
  const ok = interpolate(f, [doneAt, doneAt + 8], [0, 1], clamp);
  const active = f >= START(i) && f < doneAt;
  return (
    <div style={{height: 100, display: "flex", alignItems: "center", fontFamily: MONO, fontSize: 38}}>
      <span style={{color: C.accent, marginRight: 22, opacity: f >= START(i) ? 1 : 0.25}}>›</span>
      <span>{cmd.slice(0, n)}</span>
      {active && Math.floor(f / 6) % 2 === 0 ? <span style={{color: C.accent}}>▌</span> : null}
      <span style={{marginLeft: "auto", color: C.accent, opacity: ok, fontSize: 44}}>✓</span>
    </div>
  );
};

