      <div style={{fontFamily: MONO, fontSize: 40, color: C.text}}>{big}</div>
      <div style={{fontSize: 30, color: C.dim, marginTop: 8}}>{small}</div>
    </div>
  </Reveal>
);

export default function Scene() {
  const f = useCurrentFrame();
  const w = useIn(215, 20);
  const pulse = 1 + 0.18 * Math.sin(f * 0.2);
