import {C, MONO, Reveal, Stage, useIn} from "./lib/kit";

const NODES = [
  {t: "Micro", s: "appui F9"},
  {t: "Transcription", s: "OpenAI"},
  {t: "Agent", s: "OpenAI Responses"},
  {t: "Outils", s: "3 outils"},
  {t: "Voix", s: "synthèse vocale"},
];
const W = 240;
const STEP = 360;

const Node: React.FC<{i: number; dotX: number}> = ({i, dotX}) => {
  const e = useIn(20 + i * 14);
  const cx = i * STEP + W / 2;
  const near = Math.abs(dotX - cx) < 140;
  return (
    <div style={{position: "absolute", left: i * STEP, top: 0, width: W, height: 170, borderRadius: 24, background: C.panel, border: `3px solid ${near ? C.accent : C.line}`, boxShadow: near ? `0 0 40px ${C.accent}44` : "none", opacity: e, transform: `translateY(${interpolate(e, [0, 1], [40, 0])}px)`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10}}>
      <div style={{fontSize: 44, fontWeight: 700, color: near ? C.accent : C.text}}>{NODES[i].t}</div>
      <div style={{fontSize: 26, color: C.dim, fontFamily: MONO}}>{NODES[i].s}</div>
    </div>
  );
};

export default function Scene() {
  const f = useCurrentFrame();
  const x0 = W / 2;
  const total = 4 * STEP;
